// Chat_ConnectStreamServer is the server handle for the connect stream.
class Chat_ConnectStreamServer {
public:
	explicit Chat_ConnectStreamServer(std::shared_ptr<scg::rpc::ServerStream> stream) : stream_(stream) {}

	inline scg::rpc::StreamRecv<::pingpong::ChatMessage> recv()
	{
		scg::rpc::StreamRecv<::pingpong::ChatMessage> res;
		scg::serialize::Reader reader({});
		res.state = stream_->recv(reader, res.error);
		if (res.state == scg::rpc::StreamRecvState::Message) {
			auto err = reader.read(res.message);
			if (err) {
				res.state = scg::rpc::StreamRecvState::Closed;
				res.error = err;
			}
		}
		return res;
	}

	inline scg::rpc::StreamRecv<::pingpong::ChatMessage> tryRecv()
	{
		scg::rpc::StreamRecv<::pingpong::ChatMessage> res;
		scg::serialize::Reader reader({});
		res.state = stream_->tryRecv(reader, res.error);
		if (res.state == scg::rpc::StreamRecvState::Message) {
			auto err = reader.read(res.message);
			if (err) {
				res.state = scg::rpc::StreamRecvState::Closed;
				res.error = err;
			}
		}
		return res;
	}
	inline scg::error::Error send(const ::pingpong::ChatMessage& msg)
	{
		return stream_->send(msg);
	}

	inline const scg::context::Context& context() const
	{
		return stream_->context();
	}

private:
	std::shared_ptr<scg::rpc::ServerStream> stream_;
};

