class PingPongServer {
public:
	virtual ~PingPongServer() = default;
	
	virtual std::pair<::pingpong::PongResponse, scg::error::Error> ping(const scg::context::Context& ctx, const ::pingpong::PingRequest& req) = 0;
	
};

class PingPong_ServerStub {
public:
	PingPong_ServerStub(std::shared_ptr<PingPongServer> impl) : impl_(impl) {}

	
	std::vector<uint8_t> handlePing(const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) {
		::pingpong::PingRequest req;
		auto err = reader.read(req);
		if (err) {
			return scg::rpc::respondWithError(requestID, err);
		}

		auto handler = [this](scg::context::Context& handlerCtx, const scg::type::Message& r) -> std::pair<std::shared_ptr<scg::type::Message>, scg::error::Error> {
			// handle the request passed down the middleware chain, which a
			// middleware may have replaced
			const auto* typedReq = dynamic_cast<const ::pingpong::PingRequest*>(&r);
			if (!typedReq) {
				return std::make_pair(nullptr, scg::error::Error("Invalid request type"));
			}
			auto [resp, handlerErr] = impl_->ping(handlerCtx, *typedReq);
			if (handlerErr) {
				return std::make_pair(nullptr, handlerErr);
			}
			return std::make_pair(std::make_shared<::pingpong::PongResponse>(std::move(resp)), nullptr);
		};

		auto result = scg::middleware::applyHandlerChain(const_cast<scg::context::Context&>(ctx), req, middleware, handler);
		if (result.second) {
			return scg::rpc::respondWithError(requestID, result.second);
		}

		auto resp = std::dynamic_pointer_cast<::pingpong::PongResponse>(result.first);
		if (!resp) {
			return scg::rpc::respondWithError(requestID, scg::error::Error("Invalid response type"));
		}

		auto response = scg::rpc::respondWithMessage(requestID, *resp);
		return response;
	}
	
	std::vector<uint8_t> handleWrapper(const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) {
		uint64_t methodID = 0;
		auto err = reader.read(methodID);
		if (err) {
			return scg::rpc::respondWithError(requestID, err);
		}
		switch (methodID) {
		case pingPongServer_PingID:
			return handlePing(ctx, middleware, requestID, reader);
		default:
			return scg::rpc::respondWithError(requestID, scg::error::Error("Unrecognized method ID: " + std::to_string(methodID)));
		}
	}

	scg::error::Error handleStreamWrapper(const scg::context::Context& ctx, std::shared_ptr<scg::rpc::ServerStream> stream, uint64_t methodID) {
		(void)ctx;
		// no streaming methods
		(void)stream;
		return scg::error::Error("Unrecognized stream method ID: " + std::to_string(methodID));
	}

private:
	std::shared_ptr<PingPongServer> impl_;
};

inline void registerPingPongServer(scg::rpc::Server* server, std::shared_ptr<PingPongServer> impl) {
	auto stub = std::make_shared<PingPong_ServerStub>(impl);

	auto handler = [stub](const scg::context::Context& ctx, const std::vector<scg::middleware::Middleware>& middleware, uint64_t requestID, scg::serialize::Reader& reader) -> std::vector<uint8_t> {
		return stub->handleWrapper(ctx, middleware, requestID, reader);
	};

	server->registerService(pingPongServerID, "PingPong", handler);

	auto streamHandler = [stub](const scg::context::Context& ctx, std::shared_ptr<scg::rpc::ServerStream> stream, uint64_t methodID) -> scg::error::Error {
		return stub->handleStreamWrapper(ctx, stream, methodID);
	};

	server->registerStreamService(pingPongServerID, streamHandler);
}


