// Chat_UploadStreamClient is the client handle for the upload stream.
// Receiving is non-blocking via tryRecv() (drain from a game loop); a blocking
// recv() is also provided. Sending is non-blocking.
class Chat_UploadStreamClient {
public:
	explicit Chat_UploadStreamClient(std::shared_ptr<scg::rpc::ClientStream> stream) : stream_(stream) {}

	inline scg::error::Error send(const ::pingpong::ChatMessage& msg)
	{
		return stream_->send(msg);
	}

	// closeAndRecv half-closes the send direction and blocks for the single response.
	inline std::pair<::pingpong::UploadSummary, scg::error::Error> closeAndRecv()
	{
		auto err = stream_->closeSend();
		if (err) {
			return std::make_pair(::pingpong::UploadSummary{}, err);
		}
		scg::serialize::Reader reader({});
		scg::error::Error recvErr;
		auto state = stream_->recv(reader, recvErr);
		if (state != scg::rpc::StreamRecvState::Message) {
			if (recvErr) {
				return std::make_pair(::pingpong::UploadSummary{}, recvErr);
			}
			return std::make_pair(::pingpong::UploadSummary{}, scg::error::Error("stream closed before response"));
		}
		::pingpong::UploadSummary resp;
		auto derr = reader.read(resp);
		if (derr) {
			return std::make_pair(::pingpong::UploadSummary{}, derr);
		}
		return std::make_pair(resp, nullptr);
	}

	inline const scg::context::Context& context() const
	{
		return stream_->context();
	}

	// cancel terminates the stream from the client side, notifying the server so
	// its handler is torn down and failing a blocked recv() with a cancelled error.
	inline scg::error::Error cancel()
	{
		return stream_->cancel();
	}

private:
	std::shared_ptr<scg::rpc::ClientStream> stream_;
};

// ChatApi is the abstract call surface of the Chat service,
// mirroring the client call shape one-to-one. ChatClient is the RPC-backed
// implementation; tests (or alternative transports) substitute their own. Symmetric to the
// server-side ChatServer interface. Only unary rpcs are part of the interface;
// streaming rpcs stay on the concrete client.
class ChatApi {
public:
	virtual ~ChatApi() = default;
	
};

class ChatClient final : public ChatApi {
public:
	// Takes ownership of client and deletes it when the last copy of this
	// object is destroyed. Deprecated because that is easy to misuse (passing a
	// pointer owned elsewhere double-deletes it).
	[[deprecated("takes ownership of the raw pointer; pass a std::shared_ptr<scg::rpc::Client>, or a scg::rpc::Client& for a non-owning client")]]
	inline explicit
	ChatClient(scg::rpc::Client* client) : client_(client) {}

	// Non-owning: the caller must keep client alive for the lifetime of this object.
	inline explicit
	ChatClient(scg::rpc::Client& client) : client_(std::shared_ptr<scg::rpc::Client>(), &client) {}

	inline explicit
	ChatClient(std::shared_ptr<scg::rpc::Client> client) : client_(std::move(client)) {}
	
	inline std::pair<std::shared_ptr<Chat_ConnectStreamClient>, scg::error::Error> connect(const scg::context::Context& ctx) const
	{
		auto [stream, err] = client_->openStream(ctx, chatID, chat_ConnectID);
		if (err) {
			return std::make_pair(nullptr, err);
		}
		return std::make_pair(std::make_shared<Chat_ConnectStreamClient>(stream), nullptr);
	}
	
	inline std::pair<std::shared_ptr<Chat_SubscribeStreamClient>, scg::error::Error> subscribe(const scg::context::Context& ctx, const ::pingpong::SubscribeRequest& req) const
	{
		auto [stream, err] = client_->openStream(ctx, chatID, chat_SubscribeID);
		if (err) {
			return std::make_pair(nullptr, err);
		}
		auto handle = std::make_shared<Chat_SubscribeStreamClient>(stream);
		err = stream->send(req);
		if (err) {
			return std::make_pair(nullptr, err);
		}
		err = stream->closeSend();
		if (err) {
			return std::make_pair(nullptr, err);
		}
		return std::make_pair(handle, nullptr);
	}
	
	inline std::pair<std::shared_ptr<Chat_UploadStreamClient>, scg::error::Error> upload(const scg::context::Context& ctx) const
	{
		auto [stream, err] = client_->openStream(ctx, chatID, chat_UploadID);
		if (err) {
			return std::make_pair(nullptr, err);
		}
		return std::make_pair(std::make_shared<Chat_UploadStreamClient>(stream), nullptr);
	}
	

private:
	std::shared_ptr<scg::rpc::Client> client_;
};

