// PingPongApi is the abstract call surface of the PingPong service,
// mirroring the client call shape one-to-one. PingPongClient is the RPC-backed
// implementation; tests (or alternative transports) substitute their own. Symmetric to the
// server-side PingPongServer interface. Only unary rpcs are part of the interface;
// streaming rpcs stay on the concrete client.
class PingPongApi {
public:
	virtual ~PingPongApi() = default;
	
	virtual std::pair<::pingpong::PongResponse, scg::error::Error> ping(scg::context::Context& ctx, const ::pingpong::PingRequest& req) = 0;
	
};

class PingPongClient final : public PingPongApi {
public:
	// Takes ownership of client and deletes it when the last copy of this
	// object is destroyed. Deprecated because that is easy to misuse (passing a
	// pointer owned elsewhere double-deletes it).
	[[deprecated("takes ownership of the raw pointer; pass a std::shared_ptr<scg::rpc::Client>, or a scg::rpc::Client& for a non-owning client")]]
	inline explicit
	PingPongClient(scg::rpc::Client* client) : client_(client) {}

	// Non-owning: the caller must keep client alive for the lifetime of this object.
	inline explicit
	PingPongClient(scg::rpc::Client& client) : client_(std::shared_ptr<scg::rpc::Client>(), &client) {}

	inline explicit
	PingPongClient(std::shared_ptr<scg::rpc::Client> client) : client_(std::move(client)) {}
	
	inline std::pair<::pingpong::PongResponse, scg::error::Error> ping(scg::context::Context& ctx, const ::pingpong::PingRequest& req) override
	{
		::pingpong::PongResponse resp;
		auto err = ping(&resp, ctx, req);
		return std::pair(std::move(resp), err);
	}

	inline scg::error::Error ping(::pingpong::PongResponse* resp, scg::context::Context& c, const ::pingpong::PingRequest& req) const
	{
		auto handler = [this, resp](scg::context::Context& ctx, const scg::type::Message& r) -> std::pair<std::shared_ptr<scg::type::Message>, scg::error::Error> {
			// send the request passed down the middleware chain, which a
			// middleware may have replaced
			const auto* typedReq = dynamic_cast<const ::pingpong::PingRequest*>(&r);
			if (!typedReq) {
				return std::make_pair(nullptr, scg::error::Error("Invalid request type"));
			}
			auto [reader, err] = client_->call(ctx, pingPongID, pingPong_PingID, *typedReq);
			if (err) {
				return std::make_pair(nullptr, err);
			}

			err = reader.read(*resp);
			if (err) {
				return std::make_pair(nullptr, err);
			}

			return std::make_pair(std::shared_ptr<scg::type::Message>(resp, [](scg::type::Message*){}), nullptr);
		};

		auto& middleware = client_->middleware();
		return scg::middleware::applyHandlerChain(c, req, middleware, handler).second;
	}
	

private:
	std::shared_ptr<scg::rpc::Client> client_;
};

